/**
 * The one canonical expectation a pending transfer is created against. A
 * transfer proves exactly the facets it records: its source value and placement
 * selection always, the native history depths whenever it was created from a
 * canonical or history command, and the canonical revision only where the owner
 * actually has that capability. An absent revision is a truthful absence, never
 * a match against zero.
 */
type FullCanonicalExpectation = Readonly<{
  history?: DocumentHistoryState;
  revision?: number;
  selection: VisualSelectionSourceRange;
  value: string;
}>;

/** Which expectation facets a consumption boundary actually re-proves. */
type FullCanonicalExpectationFacets = Readonly<{
  history: boolean;
  revision: boolean;
  selection: boolean;
  value: boolean;
}>;

/** The canonical state read for one expectation comparison. */
type FullCanonicalObservation = Readonly<{
  history?: DocumentHistoryState;
  revision?: number;
  selection?: VisualSelectionSourceRange;
  value?: string;
}>;

/**
 * Where acceptance places the native caret, in the owner's real precedence
 * order: a paste's own document boundary wins over an accepted Preview map, and
 * a plain source projection is used only when neither is present.
 */
type FullPendingPlacement =
  | Readonly<{
      boundary: AcceptedPasteDocumentBoundary;
      kind: 'paste-boundary';
    }>
  | Readonly<{ kind: 'accepted-preview' }>
  | Readonly<{ kind: 'source' }>;

/**
 * The known-history proofs a native Undo/Redo replay carries: the exact
 * rematerialize slot a rebuild target was proved from, and the accepted table
 * presentation a replay may retain or normalize.
 */
type FullPendingHistoryProof = Readonly<{
  acceptedPreview?: VisualHistoryPreviewIdentity;
  historySnapshot?: Readonly<{
    depth: number;
    slot: VisualHistorySlot;
    snapshot: VisualHistorySnapshot;
  }>;
  selection?: Readonly<{
    sourceSelection: VisualSelectionSourceRange;
    witness: VisualHistorySelection;
  }>;
  slot?: Readonly<{ depth: number; value: VisualHistorySlot }>;
  tablePresentation?: FullHistoryTablePresentation;
  emptyParagraph?: Readonly<{
    continuity?: FullRemountEmptyParagraphContinuity;
    depth: number;
    owner: object;
    slot?: VisualHistorySlot;
    sourceOffset: number;
  }>;
}>;
type FullRemountEmptyParagraphContinuity = Readonly<{
  depth: number;
  markdown: string;
  sourceOffset: number;
  historyUndoDepth: number;
}>;

const fullRemountEmptyParagraphContinuity =
  new WeakMap<object, FullRemountEmptyParagraphContinuity>();

/**
 * One pending transfer, named by the trust contract it is created under:
 * `paste` is the ordinary Markdown transfer, `native` is a canonical edit's
 * accepted-Preview adoption, and `history` is a native Undo/Redo replay. Only
 * the variant that needs a proof carries it.
 *
 * The publisher, not the caller, captures the presentation instant: the
 * previous accepted Preview identity, the native focus owner and the
 * presentation selection. The spec names only the capture policy.
 */
type FullPendingTransferSpec = Readonly<{
  /** The operation-bound descriptor that survives later known writes. */
  correspondence?: FullPendingDomCorrespondence;
  /** The one canonical expectation acceptance and pending input re-prove. */
  expectation: FullCanonicalExpectation;
  /** The proof a known-history table replay requires. */
  historyProof?: FullPendingHistoryProof;
  /** The verified owner presentation retained while history rebuilds Preview. */
  retainedHistoryPresentation?: Readonly<{
    owned: FullOwnedDom;
    readOnly: VisualMarkdownReadOnlySnapshot;
  }>;
  kind: 'history' | 'native' | 'paste';
  /** Where acceptance places this transfer's native caret. */
  placement: FullPendingPlacement;
  /**
   * How the native caret is captured, and therefore whether the owner's own
   * immediately preceding single-line insertion may advance it: the structural
   * gap witness of the owner's own commit, or the plain native selection of a
   * history replay.
   */
  presentation: 'plain' | 'structural';
  /** The accepted replacement this placement must stay inside. */
  replacement?: CanonicalReplacementBoundary;
  /** The accepted-source fallback this transfer may use for its caret. */
  selectionFallback?: 'caret' | 'reflow-caret';
  /** The trusted origin an accepted-selection transition re-authenticates. */
  selectionOrigin?: FullAcceptedSelectionOrigin;
}>;

type PendingMarkdownTransfer = Readonly<{
  focusOwner?: Element | null;
  phase: 'rendering' | 'requesting';
  previousPreview: Readonly<{ revision: number; signature: string }>;
  restoreFocus?: boolean;
  signature: string;
  spec: FullPendingTransferSpec;
  visualSelection: VisualHistorySelection | null;
}>;

type CanonicalReplacementBoundary = Readonly<{
  blockId: string;
  caretOffset: number;
	caretPath: ReadonlyArray<number>;
	postSelection: VisualSelectionSourceRange;
	postSourceRange: Readonly<{ end: number; start: number }>;
	serializedBlock: string;
	sourceBlockMarkdown: string;
  sourceRange: Readonly<{ end: number; start: number }>;
}>;

type NativeTextReplacementBoundary = Readonly<{
  end: number;
  path: ReadonlyArray<number>;
  start: number;
}>;

type VisualSelectionSourceRange = Readonly<{
  direction: 'backward' | 'forward' | 'none';
  end: number;
  start: number;
}>;

/**
 * The frozen metadata of one top-level node of an owned surface. Element
 * attributes and data-node bytes are captured at publication, because the live
 * node's own attributes would otherwise be the very mutation a later
 * comparison is meant to detect.
 */
type FullOwnedNodeMetadata =
  | Readonly<{
      attributes: ReadonlyArray<VisualProtectedNodeAttribute>;
      kind: 'element';
      localName: string;
      namespaceURI: string | null;
    }>
  | Readonly<{
      data: string | null;
      kind: 'data';
      nodeType: number;
    }>;

/**
 * The verified current DOM/source pairing of this owner: the node ledger it
 * published at a real owner operation, with immutable metadata. It is not a
 * document store - `source`/`visual` are the existing strings.
 */
type FullOwnedDom = Readonly<{
  domPairToken?: number;
  rollbackCertificate?: FullMapCertificate | null;
  rollbackHtml?: string | null;
  rollbackNodes?: ReadonlyArray<Node> | null;
  metadata: ReadonlyArray<FullOwnedNodeMetadata>;
  nodes: ReadonlyArray<Node>;
  owner: object;
  source: string;
  sourceRevision: number;
  visual: string;
}>;

/**
 * A formal accepted PRE's source interval, retained by the exact PRE node that
 * the accepted render installed. This is a correspondence, not an ordinal
 * cache: a real canonical change may remove a neighboring code block and move
 * the surviving interval while the PRE identity stays mounted.
 */
type FullAcceptedCodeBodyCorrespondence = Readonly<{
  blockId: string;
  interval: VisualCodeBodyInterval;
  owner: object;
  source: string;
  sourceRevision: number;
  structureSignature: string;
}>;

/** The formal Preview origin an owned pairing still descends from. */
type FullMapCertificate = Readonly<{
  editMap: PreviewEditMap;
  html: string;
  nodes: ReadonlyArray<Node>;
  owner: object;
  previewRevision: number;
  previewSignature: string;
  source: string;
  sourceRevision: number;
  visual: string;
}>;

type FullMapApplicability = 'current' | 'invalid' | 'refresh';

/**
 * Why this owner needs exactly one more formal re-authentication for a document.
 * The reason is part of the one-attempt key, because they are different states:
 * an unproved origin and a stale known identity are expected to become current
 * after acceptance, while an absent identity is a capability the owner does not
 * supply at all.
 */
type FullRefreshReason = 'absent' | 'origin' | 'stale';

type FullSourceRow = Readonly<{
  editable: boolean;
  end: number;
  id: string;
  start: number;
}>;

type FullContextSubtarget =
  | Readonly<{ kind: 'root' }>
  | Readonly<{ kind: 'table' }>
  | Readonly<{ interval: VisualCodeBodyInterval; kind: 'code' }>
  | Readonly<{ alt: string; kind: 'image'; ordinal: number; src: string }>
  | Readonly<{
      end: number;
      href: string;
      kind: 'link';
      ordinal: number;
      start: number;
    }>
  | Readonly<{ kind: 'math' | 'mermaid'; ordinal: number; source: string }>;

/**
 * One gesture's witness in the CURRENT canonical source. It is a source range
 * plus a descriptor of the addressed DOM subtarget - never a document copy.
 */
type FullContextSourceWitness = Readonly<{
  anchor: Readonly<{ end: number; start: number }>;
  capturedKind: string;
  capturedPreviewRevision: number;
  capturedPreviewSignature: string;
  capturedRoot: HTMLElement;
  extent: Readonly<{ end: number; start: number }>;
  owner: object;
  selection: VisualSelectionSourceRange;
  selectionWasDeliberateRange: boolean;
  source: string;
  sourceRevision: number;
  subtarget: FullContextSubtarget;
}>;

type FullAcceptedSelectionOrigin = Readonly<{
  extent: Readonly<{ end: number; start: number }>;
  kind: string;
  owner: object;
  selection: VisualSelectionSourceRange;
  selectionProvenance: 'authored' | 'owner' | 'unknown';
  source: string;
  sourceRevision: number;
}>;

/** Issued only by a proved accepted paragraph-to-table normalization. */
type FullAcceptedTablePresentation = Readonly<{
  extent: Readonly<{ end: number; start: number }>;
  offset: number;
  owner: object;
  source: string;
}>;

/** One actual native history command targeting an existing source-owned slot. */
type FullHistoryTablePresentation = Readonly<{
  canNormalize: boolean;
  depth: number;
  history: DocumentHistoryState;
  originSource: string;
  owner: object;
  presentation: FullAcceptedTablePresentation;
  revision: number;
  selection: VisualSelectionSourceRange;
  slot: VisualHistorySlot;
}>;

/**
 * The actual canonical splice an already-pending transfer was created from.
 * Only the numeric descriptor is retained: the inserted Text itself stays in
 * the document and its history.
 */
type FullPendingDomCorrespondence = Readonly<{
  change: ChangeDesc;
  history: DocumentHistoryState;
  insertionOwner: HTMLElement | null;
  origin: FullOwnedDom;
  owner: object;
  source: string;
  sourceRevision: number;
}>;

/**
 * One owner presentation normalization, armed only around the real synchronous
 * canonical selection write. The lease reads it exactly once.
 */
type FullAcceptedSelectionPublication = {
  active: boolean;
  readonly after: EditorContextMenuSurfaceSnapshot;
  readonly before: EditorContextMenuSurfaceSnapshot;
  consumed: boolean;
  readonly editMap: PreviewEditMap;
  readonly extent: Readonly<{ end: number; start: number }>;
  readonly history: DocumentHistoryState;
  readonly lease: EditorContextMenuTargetLease;
  readonly owner: object;
  readonly previewRevision: number;
  readonly previewSignature: string;
  readonly root: HTMLElement;
  readonly transfer: PendingMarkdownTransfer;
};

type FullContextLeaseState = {
  lease: EditorContextMenuTargetLease;
  nativeSelection: VisualHistorySelection | null;
  publication: FullAcceptedSelectionPublication | null;
  released: boolean;
  witness: FullContextSourceWitness;
};

type FullResolvedContextTarget = {
  /** The fresh semantic element this resolve proved (an image, a TABLE, ...). */
  readonly element: Element;
  readonly extent: Readonly<{ end: number; start: number }>;
  readonly map: PreviewEditMap;
  /**
   * Whether this binding's one changed-kind whole-row publication has already
   * happened. Preparation is re-entrant for the same gesture, and the user may
   * legitimately place a caret inside the accepted row afterwards; the
   * whole-row expansion belongs to the transition, not to every later
   * preparation of the same binding.
   */
  published: boolean;
  readonly root: HTMLElement;
  readonly signature: string;
  readonly witness: FullContextSourceWitness;
};

/**
 * One short-lived native structural transition: the typed fallback for
 * `insertParagraph` inside a direct paragraph. The browser owns that split, so
 * the provenance is the captured addressed root, its exact range and the two
 * expected fragment serializations - not a new mutation observer.
 */
type FullPendingNativeRootTransition = {
  readonly kind: 'split';
  candidate: Readonly<{
    metadata: ReadonlyArray<FullOwnedNodeMetadata>;
    nodes: ReadonlyArray<Node>;
  }> | null;
  readonly afterFragment: string;
  readonly beforeFragment: string;
  readonly originalRoot: HTMLElement;
  readonly owner: object;
  readonly range: Readonly<{
    endNode: Node;
    endOffset: number;
    startNode: Node;
    startOffset: number;
  }>;
  readonly source: string;
  readonly sourceRevision: number;
  readonly sourceOffset: number | null;
  readonly visual: string;
  readonly windowIndex: number;
  splitOrder: 'after' | 'before' | null;
};

/**
 * One short-lived native root join. The browser's target range is captured
 * before the mutation and the resulting ledger is consumed once.
 */
type FullPendingNativeRootJoin = {
  readonly kind: 'join';
  candidate: Readonly<{
    metadata: ReadonlyArray<FullOwnedNodeMetadata>;
    nodes: ReadonlyArray<Node>;
  }> | null;
  readonly interRoot: ReadonlyArray<Node>;
  readonly hasFollowingRoot: boolean;
  readonly joinRoot: HTMLElement;
  readonly lineEndingLength: number;
  readonly mergedRoot?: HTMLElement;
  readonly owner: object;
  readonly preRoot: HTMLElement;
  readonly preRootSerialization: string | null;
  readonly sharedTerminal: boolean;
  readonly source: string;
  readonly sourceRevision: number;
  readonly sourceRange?: Readonly<{ end: number; start: number }>;
  /**
   * The browser's non-paragraph join shape: it removes the paragraph and
   * appends its text to the retained block. Only a single insertion of that
   * exact text may change the block's own text content.
   */
  readonly textJoin?: Readonly<{
    joinText: string;
    preRootText: string;
    tagName: string;
  }>;
  readonly visual: string;
  readonly terminal: Text | null;
  readonly terminalBefore: string;
  readonly windowIndex: number;
};

type FullPendingNativeRange = {
  readonly kind: 'range';
  readonly allowTerminalBreak: boolean;
  candidate: Readonly<{
    metadata: ReadonlyArray<FullOwnedNodeMetadata>;
    nodes: ReadonlyArray<Node>;
  }> | null;
  readonly expectedRoot: HTMLElement;
  readonly firstIndex: number;
  readonly inputType: string;
  readonly lastIndex: number;
  readonly nodes: ReadonlyArray<Node>;
  readonly outsideSnapshots: ReadonlyArray<Node | null>;
  readonly owner: object;
  readonly source: string;
  readonly sourceRevision: number;
  readonly canonicalEdit?: Readonly<{ start: number; end: number; insert: string; historySelectionBefore: VisualSelectionSourceRange }>;
  readonly terminalResidual?: Readonly<{
    root: HTMLElement;
    child: Text;
    expected: HTMLElement;
  }>;
};

type FullPendingNativeImageDeletion = Readonly<{
  kind: 'image-deletion';
  expected: HTMLElement;
  inputType: string;
  nodes: ReadonlyArray<Node>;
  owner: object;
  certificate: FullMapCertificate;
  parent: Node;
  parentOffset: number;
  precedingText: Readonly<{ node: Text; path: ReadonlyArray<number>; data: string }> | null;
  removed: Node;
  retained: ReadonlyArray<Readonly<{ node: Node; metadata: FullOwnedNodeMetadata }>>;
  source: string;
  sourceRevision: number;
  sourceRange: Readonly<{ start: number; end: number }>;
  historyOffset: number;
}>;

/** The literal-text grammar one whole plain paragraph line must match. */
const FULL_LITERAL_TEXT_LINE = /^[\p{L}\p{N}][\p{L}\p{M}\p{N} ,!?;]*$/u;

function fullOwnedNodeMetadata(node: Node): FullOwnedNodeMetadata {
  if (node instanceof HTMLElement) {
    return {
      attributes: visualProtectedNodeAttributes(node),
      kind: 'element',
      localName: node.localName,
      namespaceURI: node.namespaceURI
    };
  }
  return { data: node.nodeValue, kind: 'data', nodeType: node.nodeType };
}

function fullOwnedNodeMetadataEqual(
  current: FullOwnedNodeMetadata,
  expected: FullOwnedNodeMetadata
): boolean {
  if ('element' === current.kind && 'element' === expected.kind) {
    return (
      current.localName === expected.localName
      && current.namespaceURI === expected.namespaceURI
      && visualProtectedNodeAttributesEqual(
        current.attributes,
        expected.attributes
      )
    );
  }
  if ('data' === current.kind && 'data' === expected.kind) {
    return (
      current.nodeType === expected.nodeType
      && current.data === expected.data
    );
  }
  return false;
}

/**
 * Whether the live surface is still the exact node ledger this owner verified:
 * same node objects in the same order, with their frozen attributes and data.
 */
function fullOwnedDomMatches(
  surface: HTMLElement,
  owned: FullOwnedDom
): boolean {
  const nodes = Array.from(surface.childNodes);
  if (nodes.length !== owned.nodes.length) return false;
  return nodes.every((node, index) => {
    const expected = owned.metadata[index];
    return (
      node === owned.nodes[index]
      && undefined !== expected
      && fullOwnedNodeMetadataEqual(fullOwnedNodeMetadata(node), expected)
    );
  });
}

function equivalentNativeBoundary(
  root: HTMLElement, node: Node, offset: number, expectedNode: Node, expectedOffset: number
): boolean {
  const points = (initial: Node, initialOffset: number): Array<readonly [Node, number]> => {
    const result: Array<readonly [Node, number]> = [];
    let current = initial;
    let position = initialOffset;
    while (root.contains(current)) {
      result.push([current, position]);
      if (current === root || !current.parentNode) break;
      const size = current instanceof Text ? current.length : current.childNodes.length;
      if (position !== 0 && position !== size) break;
      const index = Array.from(current.parentNode.childNodes).indexOf(current as ChildNode);
      if (index < 0) break;
      position = index + (position === size ? 1 : 0);
      current = current.parentNode;
    }
    return result;
  };
  const expected = points(expectedNode, expectedOffset);
  return points(node, offset).some(([item, position]) =>
    expected.some(([other, otherPosition]) => item === other && position === otherPosition));
}

/**
 * Whether a non-collapsed native range may own protected atoms. Its own
 * endpoints must stay outside every protected region, and every protected
 * region it intersects must be wholly inside the range; a partially covered
 * region is never admitted. `null` means the range intersected no protected
 * region at all, so an ordinary text range keeps its existing treatment.
 */
function nativeRangeWhollyContainsProtectedRegions(
  range: Range,
  nodes: Iterable<Node>
): boolean | null {
  let contained = false;
  const ownerDocument = range.startContainer.ownerDocument;
  if (!ownerDocument) return false;
  for (const node of nodes) {
    if (node.contains(range.startContainer) || node.contains(range.endContainer)) return false;
    try {
      if (!range.intersectsNode(node)) continue;
    } catch {
      return false;
    }
    const nodeRange = ownerDocument.createRange();
    try {
      nodeRange.selectNode(node);
    } catch {
      return false;
    }
    if (
      range.compareBoundaryPoints(Range.START_TO_START, nodeRange) > 0
      || range.compareBoundaryPoints(Range.END_TO_END, nodeRange) < 0
    ) return false;
    contained = true;
  }
  return contained ? true : null;
}

/**
 * Whether a composition certificate's own Text node is still the mounted node
 * that certificate was captured on. The native ownership proof and the
 * fail-closed settlement check ask exactly this one question.
 */
function compositionOriginTextIsMounted(
  surface: HTMLElement,
  origin: Readonly<{ textNode: Text }> | null
): boolean {
  return Boolean(
    origin
    && origin.textNode.isConnected
    && surface.contains(origin.textNode)
  );
}

function terminalEmptyOffset(
  surface: HTMLElement,
  ownedParagraph: HTMLParagraphElement,
  node: Node,
  offset: number
): 0 | 1 | null {
  if (0 !== offset && 1 !== offset) return null;
  return node === ownedParagraph || node === surface ? offset : null;
}

/**
 * Whether an accepted map names every mounted top-level ELEMENT, in order.
 * Inter-root separators are Text nodes, so a map only ever names elements; a
 * mounted element the map does not name at that position (a generated root) is
 * an inventory this owner cannot certify. A missing id is the ordinary
 * not-yet-adopted shape and is not by itself an unmapped render.
 */
function fullMapNamesElements(
  surface: HTMLElement,
  editMap: PreviewEditMap
): boolean {
  const elements = Array.from(surface.children);
  if (elements.length !== editMap.blocks.length) return false;
  return elements.every((element, index) => {
    const id = element.getAttribute('data-easymde-visual-block-id');
    return null === id || id === editMap.blocks[index]?.id;
  });
}

/** A row's content extent: at most its own one terminal line terminator goes. */
function fullRowContentExtent(
  source: string,
  row: FullSourceRow
): Readonly<{ end: number; start: number }> {
  const terminator = /(?:\r\n|\n|\r)$/u.exec(
    source.slice(row.start, row.end)
  );
  return {
    end: row.end - (terminator?.[0].length ?? 0),
    start: row.start
  };
}

/**
 * The canonical spelling of text a user typed as literal content. The existing
 * serializer is the only owner of punctuation escaping, so a paragraph probe
 * asks it for the same bytes ordinary native typing would commit. Sentinels
 * keep line-start context and terminal whitespace; an all-whitespace line is
 * already literal and bypasses the serializer's document trim.
 */
function projectLiteralTypingMarkdown(
  documentRef: Document,
  text: string,
  lineStart: boolean
): string {
  return text.split('\n').map((line, index) => {
    if ('' === line || '' === line.trim()) return line;
    const startsLine = (0 === index && lineStart) && !/^[ \t]/u.test(line);
    const prefix = startsLine ? '' : 'a';
    const paragraph = documentRef.createElement('p');
    paragraph.textContent = `${prefix}${line}a`;
    const serialized = serializeVisualMarkdownBlockFragment([paragraph]);
    return serialized.slice(prefix.length, serialized.length - 1);
  }).join('\n');
}

/** Whether a complete canonical row body is one or more literal text lines. */
function fullLiteralTextBody(body: string): boolean {
  const lines = body.split(/\r\n|\n|\r/u);
  return (
    0 < lines.length
    && lines.every(
      (line) => FULL_LITERAL_TEXT_LINE.test(line) && !/[\t ]$/u.test(line)
    )
  );
}

/**
 * Whether a live root is a direct paragraph containing only literal Text nodes.
 * Normalization may merge or split those nodes. No element, line break or
 * inline protected wrapper is admitted, so a browser-inserted placeholder BR
 * keeps the row unproved and it formally refreshes instead.
 */
function fullLiteralParagraphRoot(root: HTMLElement | null): boolean {
  return Boolean(
    root
    && 'P' === root.tagName
    && Array.from(root.childNodes).every(
      (node) =>
        node.nodeType === Node.TEXT_NODE
        // A raw line break inside a paragraph's own text is not the formal
        // paragraph shape: the renderer emits one paragraph per line, so such a
        // Text node cannot be the accepted root this proof compares against.
        && !/[\r\n]/u.test((node as Text).data)
    )
  );
}

/**
 * The one fenced interval covering a whole row slice, or null. The row slice is
 * disjoint from every other row, so this never reads the whole document and
 * never guesses a global code-block ordinal.
 */
function fullFenceRowInterval(
  source: string,
  row: FullSourceRow
): VisualCodeBodyInterval | null {
  if (!row.editable) return null;
  const slice = source.slice(row.start, row.end);
  let interval: VisualCodeBodyInterval;
  try {
    interval = visualCodeBodyIntervalAtOrdinal(slice, 0);
  } catch {
    return null;
  }
  if (
    'fenced' !== interval.kind
    || 0 !== interval.codeOrdinal
    || 0 !== interval.sourceBlockStart
    || slice.length !== interval.sourceBlockEnd
  ) return null;
  // An open fence's "EOF" is only a real document end when this row really
  // reaches it; a row slice is never allowed to pretend a crop is the end.
  if (!interval.closed && row.end !== source.length) return null;
  const opener = slice.slice(interval.sourceBlockStart, interval.bodyStart);
  const openerLine = opener.split(/\r\n|\n|\r/u)[0] ?? '';
  // Only a direct fence with 0-3 ordinary spaces of indentation is this proof's
  // domain: a container prefix or an indented code block is a different kind.
  if (!/^ {0,3}(?:`{3,}|~{3,})/u.test(openerLine)) return null;
  const closeLine = interval.closed
    ? slice.slice(interval.bodyEnd, interval.sourceBlockEnd)
    : '';
  if (
    interval.closed
    && !/^(?: {0,3})(?:`{3,}|~{3,})[ \t]*(?:\r\n|\n|\r)?$/u.test(closeLine)
  ) return null;
  const body = visualCodeBodyText(interval, slice);
  const lines = body.split(/\r\n|\n|\r/u);
  const contentLines =
    interval.closed && '' === lines[lines.length - 1]
      ? lines.slice(0, -1)
      : lines;
  if (
    !contentLines.every(
      (line) =>
        '' === line
        || (FULL_LITERAL_TEXT_LINE.test(line) && !/[\t ]$/u.test(line))
    )
  ) return null;
  return interval;
}

/**
 * One unchanged blank-line separator between two top-level rows. Any other
 * gap shape - a row abutting a neighbour with no separating blank line, or
 * non-blank bytes the commit never accounted for - is not boundary evidence.
 */
function fullBlankLineSeparator(gap: string): boolean {
  // Between two rows the shared projector already consumed the first row's
  // terminal terminator, so a single blank line leaves exactly ONE remaining
  // line break here. The gap must be whitespace and must contain one.
  return /^\s*(?:\r\n|\n|\r)\s*$/u.test(gap);
}

/**
 * A block the surface mounts with no editable text at all: no children, or
 * only the placeholder break native editing leaves behind. Its caret is an
 * element caret at that block's own offset 0 instead of a caret in a text run,
 * so its own content edge is the block's boundary itself. The renderer mounts
 * an emptied paragraph either way: a `<p>` while the row is still a paragraph,
 * and a bare `<div>` once the browser has respelled it.
 */
function emptyVisualGapBlock(
  node: Node | null | undefined
): node is HTMLElement {
  return node instanceof HTMLElement
    && ['DIV', 'P'].includes(node.tagName)
    && (0 === node.childNodes.length
      || null !== emptyVisualParagraphPlaceholder(node));
}

/**
 * The emptied row a caret node names. The structural producer keeps an empty
 * Text before that row's placeholder BR, so the caret may sit in that Text, on
 * the BR, or on the row itself: all three are the same canonical blank row.
 */
function emptyVisualGapRowForCaret(
  node: Node | null | undefined
): HTMLElement | null {
  if (emptyVisualGapBlock(node)) return node;
  const parent = node?.parentElement;
  if (!(node instanceof Text || node instanceof HTMLBRElement)
    || !(parent instanceof HTMLElement)
    || !['DIV', 'P'].includes(parent.tagName)
    || !emptyVisualParagraphPlaceholder(parent)) return null;
  return node === parent.firstChild || node === parent.lastChild
    ? parent
    : null;
}

/**
 * An emptied block the surface still mounts as its document's last row. It
 * holds no editable text, so its caret is an element caret at offset 0 and
 * Chromium's own join has no byte of its own to prove. The canonical block
 * boundary in front of it is then the press's whole edit.
 */
function emptiedTerminalVisualBlock(
  node: Node | null | undefined
): node is HTMLElement {
  return emptyVisualGapBlock(node) && null === node.nextElementSibling;
}

/**
 * The source row kind each discardable block spells. A shortcut only discards a
 * block whose markers outlive its body, so this mapping is what proves a
 * marker-only row is that block's own row and not another block's. A fence is
 * deliberately absent: its canonical extent is its whole fence rather than one
 * row, and the fence owners keep those presses.
 */
const EMPTIED_ROW_BLOCK_KIND_BY_TAG: Record<string, string> = {
  BLOCKQUOTE: 'Blockquote',
  H1: 'ATXHeading1',
  H2: 'ATXHeading2',
  H3: 'ATXHeading3',
  H4: 'ATXHeading4',
  H5: 'ATXHeading5',
  H6: 'ATXHeading6',
  OL: 'OrderedList',
  UL: 'BulletList'
};

/**
 * The start of the separator run a canonical source ends on, or null. An
 * emptied block mounted at the document end owns no text of its own, so the
 * canonical bytes it stands for are exactly that trailing run. The run must
 * still pass the join separator's own proof, which keeps a hard break's
 * trailing spaces (no line ending) out of the deleted interval.
 */
function fullTerminalSeparatorStart(source: string): number | null {
  let start = source.length;
  while (start > 0 && /[ \t\r\n]/u.test(source.charAt(start - 1))) start -= 1;
  return start < source.length
    && null !== fullNativeJoinSeparator(source, start, false)
    ? start
    : null;
}

/**
 * The last Text node inside a visual block, in document order: the node a caret
 * at that block's own content end belongs to. A block with no text at all has
 * none, and the caller keeps its own element-end boundary instead.
 */
function terminalVisualTextNode(root: Element): Text | null {
  const walker = root.ownerDocument.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  let last: Text | null = null;
  for (let node = walker.nextNode(); node; node = walker.nextNode()) {
    last = node as Text;
  }
  return last;
}

function fullNativeJoinSeparator(
  source: string,
  start: number,
  hasFollowingRoot: boolean
): Readonly<{ end: number; lineEnding: string }> | null {
  const suffix = source.slice(start);
  const pattern = hasFollowingRoot
    ? /^[ \t]*(?:\r\n|\r|\n)(?:[ \t]*(?:\r\n|\r|\n))+/u
    : /^[ \t]*(?:(?:\r\n|\r|\n)[ \t]*)+$/u;
  const separator = pattern.exec(suffix)?.[0] ?? '';
  const lineEnding = /\r\n|\r|\n/u.exec(separator)?.[0] ?? '';
  if (!separator || !lineEnding) return null;
  return { end: start + separator.length, lineEnding };
}

/** Current-source rendered tail and the following parser-owned reference run. */
type FullHiddenReferenceTail = Readonly<{
  block: Readonly<{ start: number; end: number }>;
  before: Readonly<{ start: number; end: number }> | null;
  previousRendered: Readonly<{ start: number; end: number }> | null;
  referencesStart: number;
}>;

function fullHiddenReferenceTail(source: string): FullHiddenReferenceTail | null {
  const last = markdownLanguage.parser.parse(source).topNode.lastChild;
  if (last?.name !== 'LinkReference' || !/^[ \t\r\n]*$/u.test(source.slice(last.to))) return null;
  let first = last;
  while (first.prevSibling?.name === 'LinkReference') {
    const previous = first.prevSibling;
    if (!/^[ \t\r\n]*$/u.test(source.slice(previous.to, first.from))) return null;
    first = previous;
  }
  const block = first.prevSibling;
  if (!block) return null;
  const before = block.prevSibling;
  let previousRendered = before;
  let nextStart = block.from;
  while (previousRendered?.name === 'LinkReference') {
    if (!/^[ \t\r\n]*$/u.test(source.slice(previousRendered.to, nextStart))) return null;
    nextStart = previousRendered.from;
    previousRendered = previousRendered.prevSibling;
  }
  if (previousRendered && !/^[ \t\r\n]*$/u.test(source.slice(previousRendered.to, nextStart))) return null;
  return { block: { start: block.from, end: block.to },
    before: before ? { start: before.from, end: before.to } : null,
    previousRendered: previousRendered ? { start: previousRendered.from, end: previousRendered.to } : null,
    referencesStart: first.from };
}

function fullHiddenReferenceSourceRow(
  source: string,
  tail: FullHiddenReferenceTail | null,
  selection: Readonly<{ start: number; end: number }>
): Readonly<{ start: number; end: number }> | undefined {
  if (!tail || selection.start !== selection.end) return undefined;
  // A structural deletion can leave its canonical caret inside the retained
  // blank separator before this row while the native caret names its empty
  // body. Only that one parser-bounded whitespace run is the same boundary.
  const leadingStart = tail.before && /^[ \t\r\n]*$/u.test(source.slice(tail.before.end, tail.block.start))
    ? tail.before.end : tail.block.start;
  if (selection.start < leadingStart) return undefined;
  const lineEnd = source.indexOf('\n', Math.max(tail.block.start, tail.block.end - 1));
  const contentEnd = lineEnd < 0 ? source.length : source[lineEnd - 1] === '\r' ? lineEnd - 1 : lineEnd;
  if (selection.end > contentEnd) return undefined;
  return { start: source.lastIndexOf('\n', tail.block.start - 1) + 1,
    end: lineEnd < 0 ? source.length : lineEnd + 1 };
}

/**
 * A zero-length owned paragraph may precede a source-only reference suffix.
 * Its DOM position is terminal, but its source position is not EOF. Retire
 * only the two line endings immediately before its certified body offset.
 * This proves source ranges, not a native caret: the preceding block's
 * existing endpoint owner must independently authenticate its source end.
 */
function fullHiddenReferenceGapRetirement(
  source: string,
  sourceOffset: number,
  tail: FullHiddenReferenceTail
): Readonly<{ previous: Readonly<{ start: number; end: number }>; from: number; to: number }> | null {
  if (!Number.isInteger(sourceOffset) || sourceOffset <= 0 || sourceOffset >= source.length) return null;
  const previous = tail.block;
  if (sourceOffset < previous.end || sourceOffset > tail.referencesStart) return null;
  const before = source.slice(previous.end, sourceOffset);
  const after = source.slice(sourceOffset, tail.referencesStart);
  if (!/^[ \t\r\n]*$/u.test(before) || !/^[ \t\r\n]*$/u.test(after)) return null;
  let followingEndings = 0;
  for (let index = 0; index < after.length && followingEndings < 2; index += 1) {
    if (after[index] === '\r') {
      followingEndings += 1;
      if (after[index + 1] === '\n') index += 1;
    } else if (after[index] === '\n') followingEndings += 1;
  }
  if (followingEndings < 2) return null;
  let from = sourceOffset;
  for (let count = 0; count < 2; count += 1) {
    if (source[from - 1] === '\n') {
      from -= 1;
      if (source[from - 1] === '\r') from -= 1;
    } else if (source[from - 1] === '\r') from -= 1;
    else return null;
  }
  if (from < previous.end || !coversMarkdownUnits(source, from, sourceOffset)) return null;
  return { previous, from, to: sourceOffset };
}

/**
 * The positive formal-stability domain: both complete canonical row bodies and
 * their roots stay inside a syntax class the formal renderer cannot promote
 * into another block kind. Anything outside it is unproved, not invalid.
 */
function fullPositiveRowDomain(
  beforeSource: string,
  beforeRow: FullSourceRow,
  beforeRoot: HTMLElement | null,
  afterSource: string,
  afterRow: FullSourceRow,
  afterRoot: HTMLElement | null,
  edits: ReadonlyArray<Readonly<{ end: number; replacement: string; start: number }>>,
  boundariesProved: boolean
): boolean {
  // Both outer boundaries must be document edges or unchanged blank-line
  // separators. Without that evidence a literal paragraph row could be
  // concatenating with a neighbour whose own kind is not part of this proof.
  if (!boundariesProved) return false;
  const beforeBody = beforeSource.slice(
    fullRowContentExtent(beforeSource, beforeRow).start,
    fullRowContentExtent(beforeSource, beforeRow).end
  );
  const afterBody = afterSource.slice(
    fullRowContentExtent(afterSource, afterRow).start,
    fullRowContentExtent(afterSource, afterRow).end
  );
  // A blank row is not a literal paragraph; an empty half is allowed, because
  // the browser's own empty paragraph is the supported split shape.
  if (
    fullLiteralParagraphRoot(beforeRoot)
    && fullLiteralParagraphRoot(afterRoot)
    && ('' === beforeBody || fullLiteralTextBody(beforeBody))
    && ('' === afterBody || fullLiteralTextBody(afterBody))
    && edits.every(
      (edit) => !/[\r\n]/u.test(edit.replacement)
    )
  ) return true;
  const beforeFence = fullFenceRowInterval(beforeSource, beforeRow);
  const afterFence = fullFenceRowInterval(afterSource, afterRow);
  if (
    !beforeFence
    || !afterFence
    || 'PRE' !== beforeRoot?.tagName
    || 'PRE' !== afterRoot?.tagName
    || beforeFence.fence !== afterFence.fence
    || beforeFence.info !== afterFence.info
    || beforeFence.closed !== afterFence.closed
    || beforeFence.lineEnding !== afterFence.lineEnding
  ) return false;
  // Every atomic edit has to be inside the actual body: an edited opener,
  // closer or info string would move the topology the fence owns. These edits
  // are expressed relative to the row's own slice (the same space
  // `beforeFence.bodyStart/bodyEnd` are measured in), never in document
  // coordinates.
  return edits.every(
    (edit) =>
      !/[\r\n]/u.test(edit.replacement)
      && edit.start >= beforeFence.bodyStart
      && edit.end <= beforeFence.bodyEnd
  );
}

/** The number of bytes one change set moved before a source offset. */
function fullChangeDeltaAt(change: ChangeDesc, offset: number): number {
  let delta = 0;
  change.iterChangedRanges((fromA, toA, fromB, toB) => {
    if (toA <= offset) delta += (toB - fromB) - (toA - fromA);
    else if (fromA < offset) delta = Number.NaN;
  });
  return delta;
}

/**
 * Transport one origin source extent through an actual canonical splice. Only
 * the real operation's numeric descriptor decides what survived: a removal or
 * replacement overlapping the target loses it, a foreign insertion inside it is
 * ambiguous, and a pure insertion owned by the target extends it.
 */
export function fullTransportedExtent(
  correspondence: FullPendingDomCorrespondence,
  extent: Readonly<{ end: number; start: number }>,
  insertionOwner: HTMLElement | null
): Readonly<{ end: number; start: number }> | null {
  const { change, origin, source: currentSource } = correspondence;
  const ownedInsertion = null !== insertionOwner;
  const overlapsRemoval = (() => {
    let removed = false;
    change.iterChangedRanges((fromA, toA) => {
      if (fromA === toA) return;
      if (fromA < extent.end && toA > extent.start) removed = true;
    });
    return removed;
  })();
  if (overlapsRemoval) return null;
  // A pure insertion inside the target belongs to it only when this root
  // actually owns the operation. Without that proof the interior content is
  // unknown, so the window is not an unaffected survivor.
  let unownedInteriorInsertion = false;
  change.iterChangedRanges((fromA, toA) => {
    if (fromA !== toA || ownedInsertion) return;
    if (fromA > extent.start && fromA < extent.end) {
      unownedInteriorInsertion = true;
    }
  });
  if (unownedInteriorInsertion) return null;
  const start = change.mapPos(extent.start, ownedInsertion ? -1 : 1);
  const end = change.mapPos(extent.end, ownedInsertion ? 1 : -1);
  if (!Number.isSafeInteger(start) || !Number.isSafeInteger(end) || end < start)
    return null;
  // Rebuild the transported window from the origin bytes plus the operation's
  // actual insertions, and require it to equal the current canonical bytes.
  let expected = '';
  let cursor = extent.start;
  let valid = true;
  change.iterChangedRanges((fromA, toA, fromB, toB) => {
    if (!valid) return;
    if (
      fromA !== toA
        ? toA <= extent.start || fromA >= extent.end
        : fromA < extent.start || fromA > extent.end
    ) return;
    if (fromA < cursor) {
      valid = false;
      return;
    }
    expected += origin.source.slice(cursor, fromA);
    if (fromA !== toA) {
      valid = false;
      return;
    }
    if (fromA > extent.start && fromA < extent.end) {
      expected += currentSource.slice(fromB, toB);
    } else if (fromA === extent.start && ownedInsertion) {
      // The same root owns these prefix bytes, including an empty extent.
      expected += currentSource.slice(fromB, toB);
    } else if (fromA === extent.end && ownedInsertion) {
      expected += currentSource.slice(fromB, toB);
    }
    cursor = toA;
  });
  if (!valid) return null;
  expected += origin.source.slice(cursor, extent.end);
  if (currentSource.slice(start, end) !== expected) return null;
  return { end, start };
}

/**
 * The closing fence is the authenticated code-block boundary. The line
 * ending after that fence is document separator state and may be removed when
 * a neighboring EOF block disappears; it must not make the surviving PRE's
 * correspondence fail closed.
 */
function fullCodeBlockSyntaxEnd(
  source: string,
  interval: VisualCodeBodyInterval
): number {
  if ('fenced' !== interval.kind || !interval.closed || interval.sourceBlockEnd <= interval.sourceBlockStart) {
    return interval.sourceBlockEnd;
  }
  const trailing = source.slice(
    Math.max(interval.sourceBlockStart, interval.sourceBlockEnd - 2),
    interval.sourceBlockEnd
  );
  const lineEnding = /(?:\r\n|\r|\n)$/u.exec(trailing)?.[0];
  return interval.sourceBlockEnd - (lineEnding?.length ?? 0);
}

/**
 * The canonical descriptor of one actual owner write against the exact source
 * it replaced. `lineSep` is explicit so UTF-16 lengths are literal, never
 * normalized by the adapter.
 */
function fullChangeDescriptor(
  beforeSource: string,
  afterSource: string,
  change: Readonly<{ from: number; insert: string; to: number }>
): ChangeDesc | null {
  let desc: ChangeDesc;
  try {
    const set = ChangeSet.of(
      [{ from: change.from, insert: change.insert, to: change.to }],
      beforeSource.length,
      '\n'
    );
    desc = set.desc;
  } catch {
    return null;
  }
  if (desc.length !== beforeSource.length || desc.newLength !== afterSource.length)
    return null;
  return desc;
}

/** Whether one actual descriptor reconstructs exactly this source pair. */
function fullChangeMatchesSourcePair(
  change: ChangeDesc,
  beforeSource: string,
  afterSource: string
): boolean {
  if (
    change.length !== beforeSource.length
    || change.newLength !== afterSource.length
  ) return false;
  let cursor = 0;
  let expected = '';
  let valid = true;
  change.iterChangedRanges((fromA, toA, fromB, toB) => {
    if (
      !valid
      || fromA < cursor
      || fromA > toA
      || fromB > toB
      || toA > beforeSource.length
      || toB > afterSource.length
    ) {
      valid = false;
      return;
    }
    expected += beforeSource.slice(cursor, fromA);
    expected += afterSource.slice(fromB, toB);
    cursor = toA;
  });
  return valid && expected + beforeSource.slice(cursor) === afterSource;
}

function fullChangeDescriptorForEdits(
  beforeSource: string,
  afterSource: string,
  edits: ReadonlyArray<VisualMarkdownMergeEdit>
): ChangeDesc | null {
  let desc: ChangeDesc;
  try {
    const changes = edits
      .slice()
      .sort((left, right) => left.start - right.start)
      .map((edit) => ({
        from: edit.start,
        insert: edit.replacement,
        to: edit.end
      }));
    desc = ChangeSet.of(changes, beforeSource.length, '\n').desc;
  } catch {
    return null;
  }
  if (
    desc.length !== beforeSource.length
    || desc.newLength !== afterSource.length
  ) return null;
  return desc;
}

function fullIdentityChangeDescriptor(source: string): ChangeDesc | null {
  try {
    return ChangeSet.of([], source.length, '\n').desc;
  } catch {
    return null;
  }
}

/**
 * Compose one explicitly witnessed owner transition onto a cumulative
 * accepted-source descriptor. The source pair is checked by applying the
 * exact edits to the previous source; no text matching or guessed diff is
 * admitted.
 */
export function fullComposeDomCorrespondence(
  prior: FullPendingDomCorrespondence,
  origin: FullOwnedDom,
  changes: ReadonlyArray<Readonly<{ from: number; insert: string; to: number }>>,
  before: string,
  after: string,
  beforeRevision: number | undefined,
  afterRevision: number | undefined,
  beforeHistory: DocumentHistoryState,
  afterHistory: DocumentHistoryState
): FullPendingDomCorrespondence | null {
  if (
    prior.origin !== origin
    || prior.owner !== origin.owner
    || prior.source !== before
    || prior.sourceRevision !== beforeRevision
    || prior.history.undoDepth !== beforeHistory.undoDepth
    || prior.history.redoDepth !== beforeHistory.redoDepth
    || !Number.isSafeInteger(beforeRevision)
    || !Number.isSafeInteger(afterRevision)
    || afterRevision !== (beforeRevision as number) + 1
  ) return null;
  let offset = 0;
  let observed = '';
  for (const change of changes) {
    if (
      !Number.isSafeInteger(change.from)
      || !Number.isSafeInteger(change.to)
      || change.from < offset
      || change.to < change.from
      || change.to > before.length
    ) return null;
    observed += before.slice(offset, change.from) + change.insert;
    offset = change.to;
  }
  observed += before.slice(offset);
  if (observed !== after) return null;
  let next: ChangeDesc;
  try {
    next = ChangeSet.of(changes, before.length, '\n').desc;
  } catch {
    return null;
  }
  let composed: ChangeDesc;
  try {
    composed = prior.change.composeDesc(next);
  } catch {
    return null;
  }
  if (
    composed.length !== origin.source.length
    || composed.newLength !== after.length
  ) return null;
  return {
    change: composed,
    history: afterHistory,
    insertionOwner: null,
    origin,
    owner: origin.owner,
    source: after,
    sourceRevision: afterRevision as number
  };
}

function fullAcceptedDomCorrespondenceApplies(
  candidate: FullPendingDomCorrespondence | null,
  owner: object,
  currentSourceMarkdown: string | null,
  currentRevision: number | null,
  currentHistory: DocumentHistoryState
): candidate is FullPendingDomCorrespondence {
  return Boolean(
    candidate
    && candidate.owner === owner
    && candidate.origin.owner === owner
    && candidate.source === currentSourceMarkdown
    && candidate.sourceRevision === currentRevision
    && candidate.history.undoDepth === currentHistory.undoDepth
    && candidate.history.redoDepth === currentHistory.redoDepth
    && fullChangeMatchesSourcePair(
      candidate.change,
      candidate.origin.source,
      candidate.source
    )
  );
}

export function fullSelectAcceptedDomCorrespondence(
  candidates: ReadonlyArray<FullPendingDomCorrespondence | null>,
  owner: object,
  currentSourceMarkdown: string | null,
  currentRevision: number | null,
  currentHistory: DocumentHistoryState
): FullPendingDomCorrespondence | null {
  for (const candidate of candidates) {
    if (fullAcceptedDomCorrespondenceApplies(
      candidate,
      owner,
      currentSourceMarkdown,
      currentRevision,
      currentHistory
    )) return candidate;
  }
  return null;
}

function canonicalChangeRemovesVisualBlock(
  sourceMarkdown: string,
  sourceRange: Readonly<{ end: number; start: number }>,
  change: Readonly<{ from: number; insert: string; to: number }>
): boolean {
  return (
    change.insert === '' &&
    change.from === sourceRange.start &&
    /^\s*$/u.test(sourceMarkdown.slice(change.to, sourceRange.end))
  );
}

function directVisualBlockForSelectionNode(
  surface: HTMLElement,
  node: Node | null
): HTMLElement | null {
  if (!node || !surface.contains(node)) return null;
  let element =
    node instanceof HTMLElement ? node : (node.parentElement ?? null);
  while (element && element.parentElement !== surface) {
    element = element.parentElement;
  }
  return element?.parentElement === surface ? element : null;
}

/**
 * The rendered table a canonical table occupies: the block the renderer wraps
 * around the table root. That wrapper is the top-level block - its own block id
 * belongs to the SECTION, not the TABLE - so a junction beside a table is read
 * through it.
 */

/**
 * Whether an inline link's own top-level block is followed by a rendered
 * table-container. The label-tail projection may then read the last inline
 * link before that table even though the link is not at the document end.
 */
function inlineLinkFacesRenderedTable(link: Element | null): boolean {
  if (!link) return false;
  let block: Node | null = link.closest('[data-easymde-visual-block-id]');
  if (!block) return false;
  let sibling = block.nextSibling;
  while (sibling instanceof Text && /^[ \t\r\n]*$/u.test(sibling.data)) {
    sibling = sibling.nextSibling;
  }
  return renderedTableRoot(sibling);
}

/** The last inline link whose remaining source is a trailing table. */
function lastInlineLinkBeforeTrailingTable(source: string): RegExpExecArray | null {
  const pattern = /\[([^\]]*)\]\([^)]*\)/gu;
  let last: RegExpExecArray | null = null;
  for (let match = pattern.exec(source); match; match = pattern.exec(source)) {
    last = match;
  }
  if (!last) return null;
  return /^\s*\|/u.test(source.slice(last.index + last[0].length)) ? last : null;
}

function renderedTableRoot(node: Node | null): node is HTMLElement {
  return node instanceof HTMLElement
    && node.matches('section.table-container, section.easymde-table-container')
    && null !== node.querySelector('table');
}

/**
 * The interior deletion this editor commits without debouncing: a collapsed
 * caret still inside the first top-level paragraph after a rendered table.
 * The native delete has already advanced the caret when this is read, so an
 * offset above zero proves the press was not the paragraph's own leading
 * edge. The block itself is read through the same top-level selection idiom
 * used by the table and selection owners.
 */
function interiorDeletionInTableFollowingParagraph(
  surface: HTMLElement,
  selection: Selection | null | undefined
): boolean {
  const anchor = selection?.anchorNode;
  if (!selection?.isCollapsed || !(anchor instanceof Text)
    || !anchor.isConnected || selection.anchorOffset <= 0) return false;
  const block = directVisualBlockForSelectionNode(surface, anchor);
  return block instanceof HTMLParagraphElement
    && renderedTableRoot(block.previousElementSibling);
}

/**
 * The rendered table on one side of `node`, stepping over the renderer's own
 * separator text. Any other node between the caret and the table is content no
 * table edge owns, so it answers null.
 */
function adjacentRenderedTableRoot(
  node: Node | null,
  forward: boolean
): HTMLElement | null {
  let sibling = node;
  while (sibling instanceof Text && /^[ \t\r\n]*$/u.test(sibling.data)) {
    sibling = forward ? sibling.nextSibling : sibling.previousSibling;
  }
  return renderedTableRoot(sibling) ? sibling : null;
}

/**
 * The only bytes the renderer leaves between two top-level blocks of an
 * accepted render: whitespace carrying at most one line ending. Two tables can
 * therefore be neighbours across exactly this text and a press in the gap
 * between them is the same junction; any other text between the caret and a
 * table is content no table edge owns.
 */
function certifiedRendererSeparatorText(node: Node | null): boolean {
  return node instanceof Text
    && /^[ \t]*(?:\r\n|\r|\n)?[ \t]*$/u.test(node.data);
}

/** The caret's own text offset inside `host`, or null when it cannot be read. */
function textOffsetWithin(
  host: Node,
  node: Node,
  offset: number
): number | null {
  try {
    const documentRef = host.ownerDocument;
    if (!documentRef) return null;
    const range = documentRef.createRange();
    range.setStart(host, 0);
    range.setEnd(node, offset);
    return range.toString().length;
  } catch { return null; }
}

/** The table cell a node belongs to, or null when it is outside every cell. */
function tableCellOf(node: Node | null): HTMLElement | null {
  const element = node instanceof Element
    ? node
    : node?.parentElement ?? null;
  return element?.closest('td, th') ?? null;
}

/**
 * The table the caret faces from OUTSIDE its cells, or null. Reading order
 * continues into a table from that edge, so a Backspace in the block after a
 * table (`'after'`) and a Delete at the end of the block before it
 * (`'before'`) are the same junction - the ordered walk's, never a structural
 * join's.
 *
 * The contact is read through every shape the renderer and native editing can
 * leave beside a table:
 *  - a caret in a block whose own content edge faces the table;
 *  - a caret on a block that spells no text at all (a `<p>` or a `<div>` with
 *    nothing but its placeholder break), whose element caret IS that block's
 *    boundary;
 *  - a caret parked on the surface itself, between two of its child blocks.
 *
 * Only the renderer's own separator text is stepped over, so a press with real
 * bytes between the caret and the table is never this contact. A caret inside
 * a cell is the in-table walk's and is not a junction at all.
 */
function facingTableContact(
  surface: HTMLElement,
  backward: boolean
): Readonly<{ edge: 'after' | 'before'; root: HTMLElement; writable: boolean }> | null {
  const selection = surface.ownerDocument.defaultView?.getSelection();
  const caret = selection?.anchorNode;
  if (!selection?.isCollapsed || !caret || !surface.contains(caret)) return null;
  if (tableCellOf(caret)) return null;
  const edge = backward ? 'after' as const : 'before' as const;
  const contact = (
    node: Node | null
  ): Readonly<{ edge: 'after' | 'before'; root: HTMLElement; writable: boolean }> | null => {
    const root = adjacentRenderedTableRoot(node, !backward);
    // A protected table keeps its own refusal: the walk may never write through
    // a read-only region, so the contact is real but not the walk's.
    return root
      ? {
          edge,
          root,
          writable: !root.closest(
            `[contenteditable="false"], ${VISUAL_MARKDOWN_READ_ONLY_SELECTOR}`
          )
        }
      : null;
  };
  if (caret === surface) {
    // The caret sits in the surface's own child gap; the press reads the side
    // it moves towards.
    const index = selection.anchorOffset;
    return contact(surface.childNodes[backward ? index - 1 : index] ?? null);
  }
  const block = directVisualBlockForSelectionNode(surface, caret);
  if (!block) return null;
  // A caret parked on the table's own block root (its section) is at that
  // table's outer edge: no cell owns it, and the press reads from the side it
  // moves towards.
  const blockIsTableRoot: boolean = renderedTableRoot(block);
  if (blockIsTableRoot) {
    return {
      edge: backward ? 'after' : 'before',
      root: block,
      writable: !block.closest(
        `[contenteditable="false"], ${VISUAL_MARKDOWN_READ_ONLY_SELECTOR}`
      )
    };
  }
  if (caret === block) {
    // An element caret names a block only where the block spells no text of
    // its own; any other block has its boundary inside a text run. A block
    // that spells nothing has one caret position, and that position is its
    // element offset 0 - the offset 1 Chromium reports after a placeholder
    // break is not this boundary. Only the paragraph/div shape the renderer
    // mounts for an emptied row is that block: an emptied H1, LI, BLOCKQUOTE
    // or PRE still owns its marker or its row, so its caret is never a table
    // gap and its own owner keeps the press.
    return emptyVisualGapBlock(block)
      && '' === (block.textContent ?? '')
      && 0 === selection.anchorOffset
      ? contact(backward ? block.previousSibling : block.nextSibling)
      : null;
  }
  const offset = textOffsetWithin(block, caret, selection.anchorOffset);
  if (null === offset) return null;
  if (backward ? 0 !== offset : offset !== (block.textContent ?? '').length) {
    return null;
  }
  return contact(backward ? block.previousSibling : block.nextSibling);
}

/**
 * The caret a table's OUTER edge leads to: the last cell of the last row, at
 * that cell's own content end.
 *
 * A Backspace from the block after the table enters there, so the canonical
 * reading order continues INTO the table: the next press removes the table's
 * last text character and the ordered walk keeps stepping back, one cell at a
 * time, through the first cell of the first row as well. That cell's own text
 * is ordinary editable content; only after it is empty does the natural
 * no-preceding-character stop preserve the table's rows and columns.
 *
 * A Delete from before the table keeps the placement its edge contract already
 * named; this function does not re-specify that direction.
 *
 * The table, its rows and its cells are read from the CURRENT surface, so a
 * wrapper or table the renderer replaced is never trusted; a detached wrapper,
 * a table that is no longer rendered, or a missing row/cell answers null and
 * the press is refused instead of guessed at.
 */

/**
 * The caret a table's BEFORE edge leads to when the table's first cell has
 * become empty. Nothing precedes the first cell inside the table, so the next
 * Backspace must be the ordinary edit before the table: place the caret at the
 * last editable text of the preceding block (or, for two tables in a row, at
 * the previous table's own last cell). The table and its rows/columns are
 * never touched here.
 */
function tableBeforeEdgeCaretTarget(
  surface: HTMLElement,
  root: HTMLElement
): Readonly<{ node: Node; offset: number }> | null {
  if (!root.isConnected || !surface.contains(root)) return null;
  let previous: Node | null = root.previousSibling;
  while (previous instanceof Text && certifiedRendererSeparatorText(previous)) {
    previous = previous.previousSibling;
  }
  if (renderedTableRoot(previous)) {
    return tableEdgeCaretTarget(surface, previous);
  }
  if (previous instanceof HTMLElement) {
    let last: Text | null = null;
    let lastContent: Text | null = null;
    const walker = surface.ownerDocument.createTreeWalker(
      previous,
      NodeFilter.SHOW_TEXT
    );
    for (let current = walker.nextNode(); current; current = walker.nextNode()) {
      if (!(current instanceof Text)) continue;
      last = current;
      if (/\S/u.test(current.data)) lastContent = current;
    }
    // A block that mounts nested content (a quote, a list) frames it with the
    // renderer's own separator text. The ordinary edit before the table is the
    // previous block's last CONTENT run, so a trailing separator node is not
    // the position this press names; a block that spells no text at all keeps
    // the last node it has.
    const target = lastContent ?? last;
    // A block whose last run is a link must be left at the block's own end,
    // after the anchor. Placing inside the link label would make the next
    // Backspace the link's own deletion instead of the source unit before the
    // table. The browser normalizes this element-end caret to the preceding
    // text boundary when the next native key is pressed.
    if (target?.parentElement?.closest('a')) {
      return { node: previous, offset: previous.childNodes.length };
    }
    return target
      ? { node: target, offset: target.data.length }
      : { node: previous, offset: previous.childNodes.length };
  }
  const index = Array.prototype.indexOf.call(surface.childNodes, root);
  return index < 0 ? null : { node: surface, offset: index };
}

function tableEdgeCaretTarget(
  surface: HTMLElement,
  root: HTMLElement
): Readonly<{ node: Node; offset: number }> | null {
  if (!root.isConnected || !surface.contains(root)) return null;
  const table = root.querySelector('table');
  if (!(table instanceof HTMLTableElement)) return null;
  const row = table.rows[table.rows.length - 1];
  if (!(row instanceof HTMLTableRowElement)) return null;
  const cell = row.cells[row.cells.length - 1];
  if (!(cell instanceof HTMLTableCellElement)) return null;
  let last: Text | null = null;
  const walker = surface.ownerDocument.createTreeWalker(
    cell,
    NodeFilter.SHOW_TEXT
  );
  for (let current = walker.nextNode(); current; current = walker.nextNode()) {
    if (current instanceof Text) last = current;
  }
  return last
    ? { node: last, offset: last.data.length }
    : { node: cell, offset: cell.childNodes.length };
}

/**
 * A direct visual root the browser cannot merge across as text: a thematic
 * break or a rendered protected object. Backspace at the following block
 * start removes the whole object; it never edits through it.
 *
 * A table is not such a root. Its cells hold the caret, so the boundary in
 * front of a table is the ordinary join position between two editable
 * blocks, and removing the root there deleted the whole table on one
 * Backspace.
 */
function isAtomicVisualRoot(node: HTMLElement): boolean {
  if (node instanceof HTMLHRElement) return true;
  if (node.matches(VISUAL_MARKDOWN_READ_ONLY_SELECTOR)) {
    // Generated navigation and footnote furniture is not a document block.
    return !node.matches('.easymde-toc, .footnotes-sep, .footnotes');
  }
  return false;
}

/**
 * The protected atom drawn at one edge of `node`, walked exactly the way the
 * renderer draws that edge: an element is entered at the requested side, a
 * line break or an empty Text spells no character, and drawn text ends the
 * walk because the press then means an ordinary character deletion.
 *
 * A caret on a container's own child boundary (a quote row, a list, a
 * paragraph) has no neighbour of its own: the browser's default deletes the
 * adjacent NODE there, which for a subtree that ends in an inline atom removes
 * the protected region without touching the canonical source. This walk is what
 * names that atom from the caret's own boundary, so the owner can claim the
 * press instead of losing the region.
 *
 * Only empty subtrees are traversed to their end - the first drawn node stops
 * the walk - and `VISUAL_EDGE_WALK_BUDGET` bounds even that, so a boundary
 * beside a large empty container never turns one key press into a whole-tree
 * scan.
 */
const VISUAL_EDGE_WALK_BUDGET = 2048;
function visualEdgeAtomicRoot(
  node: Node | null,
  backward: boolean
): HTMLElement | null {
  if (!node) return null;
  const boundary = node.parentNode;
  let budget = VISUAL_EDGE_WALK_BUDGET;
  let current: Node | null = node;
  while (current) {
    if (0 > --budget) return null;
    if (
      current instanceof HTMLElement
      && current.matches(VISUAL_MARKDOWN_READ_ONLY_SELECTOR)
      && isAtomicVisualRoot(current)
    ) return current;
    if (current instanceof Text) {
      // The renderer writes its inter-block line breaks as Text. They draw
      // nothing, so they cannot be the edge this walk is looking for.
      if (!/^[ \t\r\n]*$/u.test(current.data)) return null;
    } else if (
      current instanceof HTMLElement
      && !(current instanceof HTMLBRElement)
    ) {
      const child: Node | null = backward ? current.lastChild : current.firstChild;
      if (child) {
        current = child;
        continue;
      }
    }
    // This subtree draws nothing at this edge: continue with its own
    // neighbour, and ascend only up to the container the caret's boundary
    // belongs to - never past it into another block.
    let cursor: Node | null = current;
    let next: Node | null = null;
    while (cursor && cursor !== boundary) {
      next = backward ? cursor.previousSibling : cursor.nextSibling;
      if (next) break;
      cursor = cursor.parentNode;
    }
    if (!next) return null;
    current = next;
  }
  return null;
}

/**
 * Whether the canonical source spells a rendered text run at all. The
 * serializer drops a run's trailing ASCII space where the run ends its block,
 * so a run the browser rendered with that space is still the source's own run
 * when only its visible part is spelled. Which occurrence it is stays the
 * projection's proof.
 */
function visualRunSpelledInSource(source: string, run: string): boolean {
  if (source.includes(run)) return true;
  const visible = run.replace(/ +$/u, '');
  return visible !== run && '' !== visible && source.includes(visible);
}

/**
 * The drawn text the atom stood after: the last non-whitespace Text of its
 * preceding siblings, or null when nothing is drawn there.
 */
function previousDrawnBoundaryBefore(
  atom: Node
): Readonly<{ node: Text; offset: number }> | null {
  let current: Node | null = atom.previousSibling;
  while (current) {
    if (current instanceof Text) {
      if (/\S/u.test(current.data)) {
        return { node: current, offset: current.data.length };
      }
    } else if (current instanceof HTMLElement) {
      const boundary = lastDrawnTextBoundary(current);
      if (boundary) return boundary;
    }
    current = current.previousSibling;
  }
  return null;
}

/**
 * Whether a root carries an editable interior: a descendant that can hold a
 * caret. Deleting such a root as one object would destroy text the user can
 * still edit, so the owner may only act on a root that has none - a thematic
 * break or a rendered protected object. A table (cells), a list (items) or a
 * paragraph is an editable interior: its edge is a text join, never an
 * object deletion.
 */
function hasEditableVisualInterior(node: HTMLElement): boolean {
  return null !== node.querySelector('table, td, th, li, p, pre');
}

/** A paragraph whose only content is inline image(s): no text to join. */
function isImageOnlyVisualRoot(node: HTMLElement): boolean {
  return 'P' === node.tagName
    && '' === (node.textContent ?? '').trim()
    && null !== node.querySelector('img')
    && !node.matches(VISUAL_MARKDOWN_READ_ONLY_SELECTOR);
}

/** A block that can hold the joined inline content of a previous paragraph. */
function isVisualTextJoinTarget(node: HTMLElement): boolean {
  return ['P', 'BLOCKQUOTE', 'OL', 'UL'].includes(node.tagName)
    || /^H[1-6]$/u.test(node.tagName);
}

/** The deepest inline-content container at the start of a joined block. */
function visualInlinePrependTarget(block: HTMLElement): HTMLElement {
  let target = block;
  for (;;) {
    if (!['BLOCKQUOTE', 'OL', 'UL'].includes(target.tagName)) return target;
    const first = target.firstElementChild;
    if (!(first instanceof HTMLElement)) return target;
    target = first;
  }
}

/** The deepest inline-content container at the end of a joined block. */
function visualInlineAppendTarget(block: HTMLElement): HTMLElement {
  let target = block;
  for (;;) {
    if (!['BLOCKQUOTE', 'OL', 'UL'].includes(target.tagName)) return target;
    const last = target.lastElementChild;
    if (!(last instanceof HTMLElement)) return target;
    target = last;
  }
}

/** Whether the collapsed native caret is at the visual end of `block`. */
function caretAtVisualRootEnd(block: HTMLElement): boolean {
  const selection = block.ownerDocument.defaultView?.getSelection();
  if (
    !selection?.isCollapsed
    || selection.rangeCount !== 1
    || !selection.anchorNode
    || selection.anchorNode !== selection.focusNode
    || selection.anchorOffset !== selection.focusOffset
    || !block.contains(selection.anchorNode)
  ) return false;
  const suffix = block.ownerDocument.createRange();
  suffix.selectNodeContents(block);
  suffix.setStart(selection.anchorNode, selection.anchorOffset);
  return '' === suffix.toString().trim();
}

/**
 * The restore callback for an emptied body whose caret Chromium named AFTER its
 * placeholder break, or null for every other caret.
 *
 * An emptied block holds nothing but the break the renderer leaves in it, so
 * the block's own offset 0 and offset 1 are the same caret: nothing stands
 * between them. Chromium nonetheless reports the caret at offset 1, while the
 * boundary proofs read the caret's visual position, which only offset 0 has.
 * Collapsing the caret across the placeholder therefore changes no visible
 * position - and the caller puts it back exactly where it was when the press
 * ends unclaimed, so a refused press still leaves the caret untouched.
 */
function collapsePlaceholderBodyCaret(
  surface: HTMLElement,
  body: HTMLElement
): (() => void) | null {
  const selection = surface.ownerDocument.defaultView?.getSelection();
  if (
    !selection?.isCollapsed
    || selection.anchorNode !== body
    || selection.anchorOffset !== 1
  ) return null;
  const children = Array.from(body.childNodes);
  const placeholderOnly = children.length === 0
    || (children.length === 1 && children[0] instanceof HTMLBRElement);
  if (!placeholderOnly) return null;
  selection.collapse(body, 0);
  return () => {
    surface.ownerDocument.defaultView?.getSelection()?.collapse(body, 1);
  };
}

/**
 * Whether this row can be joined as inline content: a leaf text block whose
 * body is text, not a nested structure, a rendered control (a task list's
 * checkbox) or a protected region. Anything else keeps the press as the silent
 * no-op rather than guess at a spelling.
 */
function visualJoinableRow(row: HTMLElement): boolean {
  if (!['P', 'LI'].includes(row.tagName) && !/^H[1-6]$/u.test(row.tagName)) {
    return false;
  }
  if ('' === (row.textContent ?? '').trim()) return false;
  if (row.matches(VISUAL_MARKDOWN_READ_ONLY_SELECTOR)) return false;
  return null === row.querySelector(
    `pre, table, img, hr, ul, ol, blockquote, section, input, ${VISUAL_MARKDOWN_READ_ONLY_SELECTOR}`
  );
}

/**
 * The block this row joins into: its own previous sibling, or - when the row
 * opens its container - the previous sibling of the nearest container that
 * would otherwise be left holding it. A row with nothing before it at any
 * level has no join target at all.
 */
function visualJoinTargetBefore(
  surface: HTMLElement,
  row: HTMLElement
): HTMLElement | null {
  let node: HTMLElement = row;
  for (;;) {
    const previous = node.previousElementSibling;
    if (previous instanceof HTMLElement) return previous;
    const parent: HTMLElement | null = node.parentElement;
    if (!parent || parent === surface) return null;
    if (!['BLOCKQUOTE', 'OL', 'UL'].includes(parent.tagName)) return null;
    node = parent;
  }
}

/**
 * The inline container that receives the joined row's content, or null when
 * the block before it cannot hold text. A fence, a table, a break, an image-only
 * paragraph and a protected region all refuse: appending text to them would
 * publish it as their own syntax instead of joining a text row.
 */
function visualJoinAppendTarget(target: HTMLElement): HTMLElement | null {
  // A list item is the join target for a row inside the same list: its
  // canonical row is the same one-line text, so the joined text stays inline.
  if (!isVisualTextJoinTarget(target) && !(target instanceof HTMLLIElement)) {
    return null;
  }
  if (target.matches(VISUAL_MARKDOWN_READ_ONLY_SELECTOR)) return null;
  if (isImageOnlyVisualRoot(target)) return null;
  const append = visualInlineAppendTarget(target);
  if (!['P', 'LI'].includes(append.tagName) && !/^H[1-6]$/u.test(append.tagName)) {
    return null;
  }
  if (append.matches(VISUAL_MARKDOWN_READ_ONLY_SELECTOR)) return null;
  if (null !== append.querySelector(
    `pre, table, img, hr, ul, ol, blockquote, section, input, ${VISUAL_MARKDOWN_READ_ONLY_SELECTOR}`
  )) return null;
  return append;
}

/**
 * The inline container a row at its own start joins into: the append target of
 * the block before it, or null when there is no such block or it cannot hold
 * text.
 */
function visualJoinAppendTargetBefore(
  surface: HTMLElement,
  row: HTMLElement
): HTMLElement | null {
  const target = visualJoinTargetBefore(surface, row);
  return target ? visualJoinAppendTarget(target) : null;
}

/**
 * Whether the canonical bytes between two joined blocks are exactly the row
 * separators and the joined row's own block markers - the only bytes a
 * structural join may remove. A quote row's own empty continuation line is a
 * marker too, so line endings and markers may interleave, and an ATX heading's
 * run is `#{1,6}` (its optional closing run sits after the caret, on the row
 * itself, never in these bytes). A plain paragraph row carries no marker of
 * its own, so in front of it only the separator's own line endings may go; a
 * space run there is the block above's trailing syntax (a hard break), which
 * this join never removes. Any other spelling - a task checkbox, an authored
 * character - is not this join.
 */
function visualJoinMarkerRun(
  removed: string,
  markerBearing: boolean
): boolean {
  if (!/^(?:(?:\r\n|\r|\n)|[ \t]|[-+*#>]|\d{1,9}[.)])+$/u.test(removed)) {
    return false;
  }
  if (/(?:[-+*#>]|\d{1,9}[.)])/u.test(removed)) return true;
  return !markerBearing && /^(?:\r\n|\r|\n)+$/u.test(removed);
}

/**
 * Join `row` into `appendTarget` in the DOM: its inline content moves to the
 * end of the target, the row goes, and containers the row alone kept alive go
 * with it. The caller proves the canonical bytes this removes before calling.
 */
function joinVisualMarkerRow(
  surface: HTMLElement,
  row: HTMLElement,
  appendTarget: HTMLElement
): void {
  const container: HTMLElement | null = row.parentElement;
  for (const child of Array.from(row.childNodes)) appendTarget.append(child);
  row.remove();
  let emptied: Element | null = container;
  while (
    emptied
    && emptied !== surface
    && ['BLOCKQUOTE', 'OL', 'UL'].includes(emptied.tagName)
    && '' === (emptied.textContent ?? '').trim()
    && null === emptied.querySelector('li, p, pre, table, img, hr')
  ) {
    const parent: Element | null = emptied.parentElement;
    emptied.remove();
    emptied = parent;
  }
}

/**
 * Whether a merge describes exactly one structural join: the marker run is the
 * only bytes removed, and the only bytes added are line endings that spell the
 * separator between the joined block and whatever followed it.
 */
function visualJoinEditsDescribeMarkerRun(
  edits: ReadonlyArray<VisualMarkdownMergeEdit>,
  start: number,
  end: number
): boolean {
  const ranged = edits.filter((edit) => edit.start !== edit.end);
  if (1 !== ranged.length) return false;
  const removal = ranged[0];
  if (
    !removal
    || '' !== removal.replacement
    || removal.start !== start
    || removal.end !== end
  ) return false;
  return edits.every(
    (edit) => edit.start !== edit.end || /^(?:\r\n|\r|\n)+$/u.test(edit.replacement)
  );
}

function acceptedTopLevelVisualChildren(
  surface: HTMLElement,
  editMap: PreviewEditMap
): ReadonlyArray<HTMLElement> {
  const children = Array.from(surface.children).filter(
    (child): child is HTMLElement => child instanceof HTMLElement
  );
  const seenBlockIds = new Set<string>();
  if (
    children.length !== editMap.blocks.length ||
    children.some((block, index) => {
      const id = block.getAttribute('data-easymde-visual-block-id');
      const expected = editMap.blocks[index]?.id;
      if (!id || id !== expected || seenBlockIds.has(id)) return true;
      seenBlockIds.add(id);
      return false;
    })
  ) {

 throw new Error('visual-editor-selection-map-failed');
  }
  return children;
}

/**
 * The accepted surface certificate: every top-level editable child must still
 * be the exact node the accepted render published, in order, and its content
 * must still serialize to the accepted bytes. `acceptedNodes` is the node list
 * captured with the accepted HTML, so a same-ID replacement row or an
 * unrelated child mutation is refused instead of being re-serialized into an
 * equal-looking value.
 */
function assertAcceptedTopLevelVisualSurface(
  surface: HTMLElement,
  editMap: PreviewEditMap,
  acceptedHtml: string | null,
  acceptedNodes?: ReadonlyArray<Node> | null
): void {
  if (null === acceptedHtml) {
    throw new Error('visual-editor-canonical-change-dom-stale');
  }
  const children = acceptedTopLevelVisualChildren(surface, editMap);
  if (acceptedNodes) {
    const current = Array.from(surface.childNodes);
    if (
      current.length !== acceptedNodes.length
      || current.some((node, index) => node !== acceptedNodes[index])
    ) {
      throw new Error('visual-editor-canonical-change-dom-stale');
    }
  }
  const template = surface.ownerDocument.createElement('article');
  template.innerHTML = acceptedHtml;
  const baselineById = new Map<string, HTMLElement>();
  for (const child of Array.from(template.children)) {
    if (!(child instanceof HTMLElement)) continue;
    const id = child.getAttribute('data-easymde-visual-block-id');
    if (!id || baselineById.has(id)) {
      throw new Error('visual-editor-canonical-change-dom-stale');
    }
    baselineById.set(id, child);
  }
  if (baselineById.size !== children.length) {
    throw new Error('visual-editor-canonical-change-dom-stale');
  }
  for (const child of children) {
    const id = child.getAttribute('data-easymde-visual-block-id');
    const baseline = id ? baselineById.get(id) : null;
    if (
      !baseline ||
      serializeVisualMarkdownBlockFragment([child]) !==
        serializeVisualMarkdownBlockFragment([baseline])
    ) {
      throw new Error('visual-editor-canonical-change-dom-stale');
    }
  }
}

type AcceptedTopLevelVisualWindow = Readonly<{
  blockRange: Readonly<{ end: number; start: number }>;
  /** The accepted map the selected block range was taken from. */
  editMap: PreviewEditMap;
  previewRevision: number;
  previewSignature: string;
  sourceMarkdown: string;
}>;

function captureAcceptedTopLevelVisualWindow(
  surface: HTMLElement,
  sourceMarkdown: string,
  editMap: PreviewEditMap | null | undefined,
  previewSignature: string,
  previewRevision: number,
  capturedPreviewRevision: number | null,
  acceptedPreviewSource: string | null
): AcceptedTopLevelVisualWindow | null {
  if (
    !editMap ||
    editMap.signature !== previewSignature ||
    capturedPreviewRevision !== previewRevision ||
    acceptedPreviewSource !== sourceMarkdown ||
    1 !== editMap.version ||
    'line' !== editMap.coordinate
  ) {
    return null;
  }
  // A native-created root may retain a copied id while the accepted map still
  // describes the pre-split surface. This optional window cannot authenticate
  // that topology; leave shortcut ownership to its other proofs instead of
  // invoking the strict duplicate-id assertion below.
  if (!fullMapNamesElements(surface, editMap)) return null;
  const elements = Array.from(surface.children);
  if (elements.some((element, index) => {
    const id = element.getAttribute('data-easymde-visual-block-id');
    return !id || id !== editMap.blocks[index]?.id;
  })) return null;
  const children = acceptedTopLevelVisualChildren(surface, editMap);
  const selection = surface.ownerDocument.defaultView?.getSelection();
  if (!selection?.anchorNode || !selection.focusNode) return null;
  const anchorBlock = directVisualBlockForSelectionNode(
    surface,
    selection.anchorNode
  );
  const focusBlock = directVisualBlockForSelectionNode(
    surface,
    selection.focusNode
  );
  if (!anchorBlock || !focusBlock) return null;
  const anchorIndex = children.indexOf(anchorBlock);
  const focusIndex = children.indexOf(focusBlock);
  if (anchorIndex < 0 || focusIndex < 0) return null;
  const start = Math.min(anchorIndex, focusIndex);
  const end = Math.max(anchorIndex, focusIndex) + 1;
  const mapIndices = children
    .slice(start, end)
    .map((block) =>
      editMap.blocks.findIndex(
        (candidate) =>
          candidate.id === block.getAttribute('data-easymde-visual-block-id')
      )
    );
  const firstMapIndex = mapIndices[0];
  const lastMapIndex = mapIndices[mapIndices.length - 1];
  if (
    undefined === firstMapIndex ||
    undefined === lastMapIndex ||
    mapIndices.some((index) => index < 0) ||
    mapIndices.some((index, offset) => index !== firstMapIndex + offset) ||
    editMap.blocks
      .slice(firstMapIndex, lastMapIndex + 1)
      .some((block) => !block.editable)
  ) {
    return null;
  }
  return {
    blockRange: { end: lastMapIndex + 1, start: firstMapIndex },
    editMap,
    previewRevision,
    previewSignature,
    sourceMarkdown
  };
}

function acceptedBaselineBlocksById(
  surface: HTMLElement,
  acceptedHtml: string
): Map<string, HTMLElement> {
  const template = surface.ownerDocument.createElement('article');
  template.innerHTML = acceptedHtml;
  const baselineById = new Map<string, HTMLElement>();
  for (const child of Array.from(template.children)) {
    if (!(child instanceof HTMLElement)) continue;
    const id = child.getAttribute('data-easymde-visual-block-id');
    if (!id || baselineById.has(id)) {

 throw new Error('visual-editor-selection-map-failed');
    }
    baselineById.set(id, child);
  }
  return baselineById;
}

function ownedAcceptedTopLevelVisualMerge(
  surface: HTMLElement,
  sourceMarkdown: string,
  editMap: PreviewEditMap,
  acceptedHtml: string,
  acceptedWindow: AcceptedTopLevelVisualWindow
): Readonly<{
  changes: Readonly<{ from: number; insert: string; to: number }>;
  selection: VisualSelectionSourceRange;
  value: string;
}> | null {
  if (
    acceptedWindow.sourceMarkdown !== sourceMarkdown ||
    acceptedWindow.previewSignature !== editMap.signature ||
    acceptedWindow.editMap !== editMap
  ) {
    return null;
  }
  const currentChildren = Array.from(surface.children).filter(
    (child): child is HTMLElement => child instanceof HTMLElement
  );
  const selectedMapBlocks = editMap.blocks.slice(
    acceptedWindow.blockRange.start,
    acceptedWindow.blockRange.end
  );
  const selectedIds = new Set(selectedMapBlocks.map((block) => block.id));
  const previousId = editMap.blocks[acceptedWindow.blockRange.start - 1]?.id;
  const nextId = editMap.blocks[acceptedWindow.blockRange.end]?.id;
  const previousIndex = previousId
    ? currentChildren.findIndex(
        (child) =>
          child.getAttribute('data-easymde-visual-block-id') === previousId
      )
    : -1;
  const nextIndex = nextId
    ? currentChildren.findIndex(
        (child) => child.getAttribute('data-easymde-visual-block-id') === nextId
      )
    : currentChildren.length;
  if (
    (previousId && previousIndex < 0) ||
    (nextId && nextIndex < 0) ||
    (previousIndex >= 0 && nextIndex <= previousIndex)
  ) {
    return null;
  }
  const spanStart = previousIndex + 1;
  const spanEnd = nextIndex;
  const blocks = currentChildren.slice(spanStart, spanEnd);
  if (
    !blocks.length ||
    !blocks.some((block) => block.classList.contains('markdown-block-applied'))
  ) {
    return null;
  }
  const seenSelectedIds = new Set<string>();
  for (const block of blocks) {
    const id = block.getAttribute('data-easymde-visual-block-id');
    if (id) {
      if (!selectedIds.has(id) || seenSelectedIds.has(id)) return null;
      seenSelectedIds.add(id);
    }
  }
  if (seenSelectedIds.size !== selectedIds.size) return null;
  const baselineById = acceptedBaselineBlocksById(surface, acceptedHtml);
  const expectedOutsideIds = [
    ...editMap.blocks.slice(0, acceptedWindow.blockRange.start),
    ...editMap.blocks.slice(acceptedWindow.blockRange.end)
  ].map((block) => block.id);
  const outside = [
    ...currentChildren.slice(0, spanStart),
    ...currentChildren.slice(spanEnd)
  ];
  if (outside.length !== expectedOutsideIds.length) return null;
  for (const [index, block] of outside.entries()) {
    const id = block.getAttribute('data-easymde-visual-block-id');
    const expectedId = expectedOutsideIds[index];
    const baseline = expectedId ? baselineById.get(expectedId) : null;
    if (
      !id ||
      id !== expectedId ||
      !baseline ||
      serializeVisualMarkdownBlockFragment([block]) !==
        serializeVisualMarkdownBlockFragment([baseline])
    ) {
      return null;
    }
  }
  const baselineBlocks = selectedMapBlocks.map((block) => {
    const baseline = baselineById.get(block.id);
    if (!baseline) throw new Error('visual-editor-selection-map-failed');
    return baseline;
  });
  const baselineSlice = serializeVisualMarkdownBlockFragment(baselineBlocks);
  const editedSlice = serializeVisualMarkdownBlockFragment(blocks);
  const windowChange = createVisualMarkdownWindowChange(
    sourceMarkdown,
    editMap,
    acceptedWindow.blockRange,
    baselineSlice,
    editedSlice
  );
  const relative = visualSelectionSourceRangeForBlocks(
    blocks,
    windowChange.changes.insert,
    editedSlice
  );
  return {
    changes: windowChange.changes,
    selection: {
      direction: relative.direction,
      end: windowChange.sourceRange.start + relative.end,
      start: windowChange.sourceRange.start + relative.start
    },
    value: windowChange.value
  };
}

function acceptedTopLevelVisualSelection(
  surface: HTMLElement,
  sourceMarkdown: string,
  editMap: PreviewEditMap | null | undefined,
  previewSignature: string,
  previewRevision: number,
  capturedPreviewRevision: number | null,
  acceptedPreviewSource: string | null,
  referenceDefined: (label: string) => boolean
): VisualSelectionSourceRange | null {
  const thematicBreakSelection = captureVisualThematicBreakSelection(surface);
  if (
    !editMap ||
    editMap.signature !== previewSignature ||
    capturedPreviewRevision !== previewRevision ||
    acceptedPreviewSource !== sourceMarkdown ||
    1 !== editMap.version ||
    'line' !== editMap.coordinate
  ) {
    if (thematicBreakSelection) {

 throw new Error('visual-editor-selection-map-failed');
    }
    return null;
  }
  const children = acceptedTopLevelVisualChildren(surface, editMap);
  if (thematicBreakSelection) {
    const blockIndex = children.indexOf(thematicBreakSelection.block);
    const block = blockIndex >= 0 ? editMap.blocks[blockIndex] : undefined;
    if (
      !block
      || block.id !== thematicBreakSelection.block.getAttribute(
        'data-easymde-visual-block-id'
      )
      || !block.editable
    ) {

 throw new Error('visual-editor-selection-map-failed');
    }
    const sourceRange = createVisualMarkdownSourceRangeFromPreviewEditMap(
      sourceMarkdown,
      editMap,
      { end: blockIndex + 1, start: blockIndex }
    );
    return visualThematicBreakSourceSelection(
      sourceMarkdown,
      sourceRange,
      thematicBreakSelection.direction
    );
  }
  const selection = surface.ownerDocument.defaultView?.getSelection();
  if (
    !selection?.anchorNode ||
    !selection.focusNode ||
    !selection.anchorNode.isConnected ||
    !selection.focusNode.isConnected
  ) {
    return null;
  }
  const anchorBlock = directVisualBlockForSelectionNode(
    surface,
    selection.anchorNode
  );
  const focusBlock = directVisualBlockForSelectionNode(
    surface,
    selection.focusNode
  );
  if (!anchorBlock || !focusBlock) return null;
  const anchorIndex = children.indexOf(anchorBlock);
  const focusIndex = children.indexOf(focusBlock);
  if (anchorIndex < 0 || focusIndex < 0) return null;
  const blockStart = Math.min(anchorIndex, focusIndex);
  const blockEnd = Math.max(anchorIndex, focusIndex) + 1;
  const blocks = children.slice(blockStart, blockEnd);
  if (blocks.length !== blockEnd - blockStart) {
    return null;
  }
  const mapIndices = blocks.map((block) =>
    editMap.blocks.findIndex(
      (candidate) =>
        candidate.id === block.getAttribute('data-easymde-visual-block-id')
    )
  );
  const firstMapIndex = mapIndices[0];
  const lastMapIndex = mapIndices[mapIndices.length - 1];
  if (
    undefined === firstMapIndex ||
    undefined === lastMapIndex ||
    mapIndices.some((index) => index < 0) ||
    mapIndices.some((index, offset) => index !== firstMapIndex + offset) ||
    editMap.blocks
      .slice(firstMapIndex, lastMapIndex + 1)
      .some((block) => !block.editable)
  ) {
    return null;
  }
  try {
    const sourceRange = createVisualMarkdownSourceRangeFromPreviewEditMap(
      sourceMarkdown,
      editMap,
      {
        end: lastMapIndex + 1,
        start: firstMapIndex
      }
    );
    const sourceSlice = sourceMarkdown.slice(
      sourceRange.start,
      sourceRange.end
    );
    const baselineSlice = serializeVisualMarkdownBlockFragment(blocks);
    let projectedIntervalMap: VisualMarkdownSourceIntervalMap | undefined;
    if (blocks.some((block) => block.matches('img') || block.querySelector('img'))) {
      const fragment = surface.ownerDocument.createElement('article');
      fragment.append(...blocks.map((block) => block.cloneNode(true)));
      projectedIntervalMap = createVisualMarkdownImageSourceIntervalMap(
        fragment, sourceSlice, baselineSlice, referenceDefined
      );
    }
    const relative = visualSelectionSourceRangeForBlocks(
      blocks,
      sourceSlice,
      baselineSlice,
      projectedIntervalMap
    );
    return {
      direction: relative.direction,
      end: sourceRange.start + relative.end,
      start: sourceRange.start + relative.start
    };
  } catch (error) {
    if (
      error instanceof Error &&
      [
        'visual-editor-selection-unavailable',
        'visual-editor-selection-invalid',
        'visual-editor-window-block-range-invalid',
        'visual-editor-window-source-range-invalid'
      ].includes(error.message)
    ) {

 throw new Error('visual-editor-selection-map-failed');
    }
    throw error;
  }
}

function acceptedTopLevelVisualMerge(
  surface: HTMLElement,
  sourceMarkdown: string,
  editMap: PreviewEditMap | null | undefined,
  previewSignature: string,
  previewRevision: number,
  capturedPreviewRevision: number | null,
  acceptedPreviewSource: string | null,
  acceptedHtml: string | null,
  acceptedWindow: AcceptedTopLevelVisualWindow | null
): Readonly<{
  changes: Readonly<{ from: number; insert: string; to: number }>;
  selection: VisualSelectionSourceRange;
  value: string;
}> | null {
  if (
    !editMap ||
    editMap.signature !== previewSignature ||
    capturedPreviewRevision !== previewRevision ||
    acceptedPreviewSource !== sourceMarkdown ||
    !acceptedHtml ||
    1 !== editMap.version ||
    'line' !== editMap.coordinate
  ) {
    return null;
  }
  let children: ReadonlyArray<HTMLElement>;
  try {
    children = acceptedTopLevelVisualChildren(surface, editMap);
  } catch (error) {
    if (
      !acceptedWindow ||
      acceptedWindow.previewRevision !== previewRevision ||
      acceptedWindow.previewSignature !== previewSignature
    ) {
      throw error;
    }
    return ownedAcceptedTopLevelVisualMerge(
      surface,
      sourceMarkdown,
      editMap,
      acceptedHtml,
      acceptedWindow
    );
  }
  const selection = surface.ownerDocument.defaultView?.getSelection();
  if (
    !selection?.anchorNode ||
    !selection.focusNode ||
    !selection.anchorNode.isConnected ||
    !selection.focusNode.isConnected
  ) {
    return null;
  }
  const anchorBlock = directVisualBlockForSelectionNode(
    surface,
    selection.anchorNode
  );
  const focusBlock = directVisualBlockForSelectionNode(
    surface,
    selection.focusNode
  );
  if (!anchorBlock || !focusBlock) return null;
  const anchorIndex = children.indexOf(anchorBlock);
  const focusIndex = children.indexOf(focusBlock);
  if (anchorIndex < 0 || focusIndex < 0) return null;
  const blockStart = Math.min(anchorIndex, focusIndex);
  const blockEnd = Math.max(anchorIndex, focusIndex) + 1;
  const blocks = children.slice(blockStart, blockEnd);
  const mapIndices = blocks.map((block) =>
    editMap.blocks.findIndex(
      (candidate) =>
        candidate.id === block.getAttribute('data-easymde-visual-block-id')
    )
  );
  const firstMapIndex = mapIndices[0];
  const lastMapIndex = mapIndices[mapIndices.length - 1];
  if (
    undefined === firstMapIndex ||
    undefined === lastMapIndex ||
    mapIndices.some((index) => index < 0) ||
    mapIndices.some((index, offset) => index !== firstMapIndex + offset) ||
    editMap.blocks
      .slice(firstMapIndex, lastMapIndex + 1)
      .some((block) => !block.editable)
  ) {
    return null;
  }
  const template = surface.ownerDocument.createElement('article');
  template.innerHTML = acceptedHtml;
  const baselineById = new Map<string, HTMLElement>();
  for (const child of Array.from(template.children)) {
    if (!(child instanceof HTMLElement)) continue;
    const id = child.getAttribute('data-easymde-visual-block-id');
    if (!id || baselineById.has(id)) {

 throw new Error('visual-editor-selection-map-failed');
    }
    baselineById.set(id, child);
  }
  for (const [index, child] of children.entries()) {
    if (index >= blockStart && index < blockEnd) continue;
    const id = child.getAttribute('data-easymde-visual-block-id');
    const baseline = id ? baselineById.get(id) : null;
    if (
      !baseline ||
      serializeVisualMarkdownBlockFragment([child]) !==
        serializeVisualMarkdownBlockFragment([baseline])
    ) {

 throw new Error('visual-editor-selection-map-failed');
    }
  }
  try {
    const sourceRange = createVisualMarkdownSourceRangeFromPreviewEditMap(
      sourceMarkdown,
      editMap,
      {
        end: lastMapIndex + 1,
        start: firstMapIndex
      }
    );
    const baselineBlocks = blocks.map((block) => {
      const id = block.getAttribute('data-easymde-visual-block-id');
      const baseline = id ? baselineById.get(id) : null;
      if (!baseline) {

 throw new Error('visual-editor-selection-map-failed');
      }
      return baseline;
    });
    const baselineSlice = serializeVisualMarkdownBlockFragment(baselineBlocks);
    const editedSlice = serializeVisualMarkdownBlockFragment(blocks);
    const windowChange = createVisualMarkdownWindowChange(
      sourceMarkdown,
      editMap,
      { end: lastMapIndex + 1, start: firstMapIndex },
      baselineSlice,
      editedSlice
    );
    const relative = visualSelectionSourceRangeForBlocks(
      blocks,
      windowChange.changes.insert,
      editedSlice
    );
    return {
      changes: windowChange.changes,
      selection: {
        direction: relative.direction,
        end: sourceRange.start + relative.end,
        start: sourceRange.start + relative.start
      },
      value: windowChange.value
    };
  } catch (error) {
    if (
      error instanceof Error &&
      [
        'visual-editor-selection-invalid',
        'visual-editor-window-block-range-invalid',
        'visual-editor-window-selection-invalid',
        'visual-editor-window-source-range-invalid',
        'visual-editor-markdown-merge-ambiguous',
        'visual-editor-markdown-merge-failed'
      ].includes(error.message)
    ) {

 throw new Error('visual-editor-selection-map-failed');
    }
    throw error;
  }
}

