  historyGroupOrigin?: Readonly<{
    historyRedoDepth: number;
    historySelectionBefore: VisualSelectionSourceRange;
    historyUndoDepth: number;
    owned: FullOwnedDom;
  }>;
  historyBefore?: VisualHistorySnapshot;
  historyOrigin?: 'empty-structural';
  inputType: string;
