      if (!currentSlot) {
onFailure('visual-editor-history-snapshot-missing');
        return false;
      }
      if (currentSlot.markdown !== currentMarkdown) {
onFailure('visual-editor-history-snapshot-stale');
        return false;
      }
      const previousSnapshot = captureVisualHistorySnapshot(
        currentMarkdown,
        surface.innerHTML
      );
      const retainedOwned = ownedDomRef.current;
      const retainedReadOnly = readOnlySnapshotRef.current;
      const retainedHistoryPresentation = retainedOwned && retainedReadOnly
        && retainedOwned.sourceRevision === documentSession.document.getRevision?.()
